const load=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src;});
export const vehicleAsset=design=>'/studio/mockups/'+(design.productId==='vehicle-pickup'?'pickup':design.productId==='vehicle-minivan'?'minivan':'van')+(design.options.vehicleColour==='black'?'-black':'')+'.png';
// Project the customer artwork onto photographed print surfaces; poles and frames remain visible.
function quad(ctx,art,points){const [a,b,c,d]=points;for(let y=0;y<art.height;y++){const t=y/art.height,t2=(y+1)/art.height,l=[a[0]+(d[0]-a[0])*t,a[1]+(d[1]-a[1])*t],r=[b[0]+(c[0]-b[0])*t,b[1]+(c[1]-b[1])*t],l2=[a[0]+(d[0]-a[0])*t2,a[1]+(d[1]-a[1])*t2];ctx.save();ctx.setTransform((r[0]-l[0])/art.width,(r[1]-l[1])/art.width,l2[0]-l[0],l2[1]-l[1],l[0],l[1]);ctx.drawImage(art,0,y,art.width,1,0,0,art.width,1.5);ctx.restore();}}
export async function mockupScene(design,first,second,fallback){const id=design.productId;let photo,box,quads;if(id.startsWith('vehicle-')){photo=vehicleAsset(design);box=id==='vehicle-pickup'?[410,462,544,160]:id==='vehicle-minivan'?[412,462,622,172]:[605,270,748,162];}else if(id==='roll-up-banner'){photo='/studio/mockups/rollup.png';box=[526,68,482,810];}else if(id==='a-frame-signs'){photo='/studio/mockups/aframe.png';box=[530,144,472,628];}else if(id==='x-frame-banner'){photo='/satin/img/pr-xframe-960.webp';quads=[[[175,43],[451,37],[437,819],[153,810]],[[573,88],[807,92],[827,740],[588,748]]];}else if(id==='yard-signs'){photo='/satin/img/pr-yard-sign-1100.webp';quads=[[[140,106],[512,116],[513,770],[140,779]],[[580,113],[960,106],[957,779],[580,769]]];}else if(id==='flags'){photo='/satin/img/pr-flags-row-480.webp';}else{const v=await fallback();return v.mockup;}
const image=await load(photo),c=document.createElement('canvas');c.width=image.width;c.height=image.height;const ctx=c.getContext('2d');ctx.drawImage(image,0,0);
if(quads){quads.forEach((q,i)=>quad(ctx,i===1&&second?second:first,q));}
else if(id==='flags'){for(const dx of [0,137,271]){ctx.save();ctx.beginPath();ctx.moveTo(70+dx,365);ctx.lineTo(70+dx,142);ctx.bezierCurveTo(70+dx,91,95+dx,55,126+dx,56);ctx.bezierCurveTo(157+dx,55,168+dx,73,168+dx,93);ctx.bezierCurveTo(155+dx,154,102+dx,294,70+dx,365);ctx.closePath();ctx.clip();ctx.drawImage(first,69+dx,55,100,314);const shade=ctx.createLinearGradient(69+dx,0,169+dx,0);shade.addColorStop(0,'#0003');shade.addColorStop(.3,'#fff2');shade.addColorStop(.6,'#0001');shade.addColorStop(1,'#fff2');ctx.fillStyle=shade;ctx.fillRect(69+dx,55,100,314);ctx.restore();}}
else{ctx.save();ctx.beginPath();ctx.rect(...box);ctx.clip();if(id.startsWith('vehicle-')){ctx.globalCompositeOperation=design.options.vehicleColour==='black'?'source-over':'multiply';ctx.globalAlpha=.94;}ctx.drawImage(first,...box);ctx.restore();}return c.toDataURL('image/png');}
